# -*- coding: utf-8 -*-
from pathlib import Path
import json
root=Path(__file__).resolve().parent.parent
def l(title,body,code,output,q,options,answer,ex):return {'title':title,'body':body,'code':code,'output':output,'question':q,'options':options,'answer':answer,'explanation':ex,'author':'Nunya','reviewer':None,'status':'brouillon'}
rows=[('cv-candidatures','CV et candidatures : montrer ses preuves','CV and applications','business',[
l('Relier son CV à une offre','Un CV aide une personne à repérer ce que tu peux apporter à une mission précise. Commence par lire les tâches de l’offre, puis choisis deux expériences, projets scolaires ou activités qui donnent une preuve utile. Tu peux être débutant et présenter honnêtement un projet de classe. Ne transforme pas une initiation en diplôme, et n’invente ni emploi ni compétence. Dans le brouillon, conserve seulement les informations que tu décides de partager.','Besoin fictif : organiser des informations.\nPreuve : tableau de suivi de 12 livres du club.','Une preuve précise rend une compétence plus compréhensible.','Quelle formulation donne une preuve ?',['Je sais tout faire.','J’ai créé un tableau de suivi de 12 livres, puis corrigé deux doublons.','Je suis le meilleur candidat.'],1,'Le tableau, son périmètre et la correction sont des éléments observables.'),
l('Décrire une expérience sans exagérer','Présente une activité par une action, un contexte et un résultat que tu peux expliquer. Les résultats peuvent être modestes : une page devenue lisible sur téléphone, une consigne clarifiée, un total vérifié. Si une situation est fictive, indique-le. Utilise des titres simples pour les rubriques du CV et un ordre cohérent. Un document lisible en texte aide aussi quand une plateforme extrait automatiquement les informations.','Action : relire une page du club.\nRésultat : les champs ont maintenant un libellé.\nLimite : test avec deux camarades seulement.','Une limite honnête est compatible avec une réalisation utile.','Une activité fictive doit être…',['présentée comme un emploi réel','supprimée dans tous les cas','clairement indiquée comme exercice ou projet fictif'],2,'Un projet fictif peut illustrer un apprentissage, sans être confondu avec une expérience professionnelle.'),
l('Écrire une lettre ciblée','Une lettre courte relie une demande, une motivation précise et une preuve. Évite de recopier le CV ou d’envoyer le même texte à toutes les organisations. Tu peux expliquer ce que tu souhaites apprendre pendant un stage, montrer un travail et proposer un échange. Vérifie le nom de l’organisme, la mission et les pièces demandées avant l’envoi. Le générateur local de Nunya t’aide à préparer un brouillon ; il n’envoie aucune candidature.','Objet : candidature à un stage de découverte.\nMotivation : comprendre la gestion d’un petit stock.\nPreuve : tableau fictif de suivi des livres.','La demande et la preuve parlent de la même mission.','Quel élément rend la lettre plus précise ?',['Une phrase identique pour toutes les offres.','Un lien entre la mission et une expérience que tu peux expliquer.','Une promesse d’être expert après un jour.'],1,'Le lien entre une mission et une preuve montre que la candidature a été préparée.'),
l('Vérifier l’offre et les données partagées','Une annonce peut imiter une entreprise ou proposer un emploi garanti contre un paiement urgent. Vérifie l’organisation par ses coordonnées publiques et lis les modalités sur son site officiel. Ne partage jamais un code de confirmation, un mot de passe ou un accès mobile money. Une demande inhabituelle mérite une vérification indépendante. Pour un premier contact, limite les informations personnelles ; Nunya ne garantit pas l’authenticité d’une annonce externe.','Annonce fictive : « Stage garanti, verse des frais et transmets le code SMS. »\nAction prudente : ne rien transmettre ; vérifier par le canal officiel.','Un signal suspect doit déclencher une vérification.','Que faire si une annonce demande un code secret reçu par SMS ?',['Ne pas le transmettre et vérifier l’annonce indépendamment.','L’envoyer parce que le logo paraît officiel.','Le publier dans son CV.'],0,'Un code secret donne potentiellement accès à un compte ; il n’est pas une pièce normale de candidature.')]),
('entretien-professionnel','Préparer son premier entretien','Prepare for an interview','business',[
l('Préparer une présentation courte','Une présentation de début d’entretien peut contenir ton objectif, une expérience utile et ce que tu souhaites apprendre. Il ne s’agit pas de réciter toute ta vie. Choisis des phrases simples et un exemple vrai. Pour t’entraîner, enregistre-toi localement ou lis le texte à voix haute sans envoyer de données à un service. Le but est de devenir plus clair, pas de mémoriser une réponse parfaite.','Je cherche un stage de découverte.\nJ’ai organisé les informations d’un projet de classe.\nJe souhaite apprendre comment une équipe vérifie son travail.','Trois idées suffisent pour commencer une conversation.','Une présentation utile doit surtout…',['énumérer tous les événements de sa vie','relier son objectif à un exemple précis','promettre de tout maîtriser'],1,'Un objectif et un exemple aident l’interlocuteur à comprendre ton point de départ.'),
l('Expliquer un projet et son résultat','Décris la situation, ton rôle, l’action réalisée et ce que tu as observé. Si tu as travaillé en groupe, distingue la contribution collective de la tienne. Tu peux mentionner une difficulté et la manière dont tu l’as traitée. N’invente pas de résultat chiffré : un résultat qualitatif précis vaut mieux qu’un nombre fabriqué.','Situation : page du club peu lisible.\nMon rôle : vérifier les champs.\nAction : ajouter des libellés.\nObservation : deux camarades retrouvent le champ demandé.','Le rôle personnel et l’observation sont distingués.','Dans un projet de groupe, il faut…',['s’attribuer tout le travail','cacher le travail collectif','expliquer sa contribution et celle du groupe'],2,'Décrire les contributions honnêtement permet de discuter réellement du projet.'),
l('Poser une question utile','Prépare une question sur les missions, l’accompagnement ou la façon dont le travail est évalué. Une question montre aussi que tu vérifies si le cadre te convient. Avant l’entretien, lis les informations publiques de l’organisme. Tu peux demander une précision plutôt que deviner. Les conditions de stage et d’emploi dépendent de l’organisme et de ta situation ; vérifie-les auprès des interlocuteurs compétents.','Question possible : « Quel type de tâche un débutant réalise-t-il avec accompagnement ? »','La question porte sur le travail et l’apprentissage.','Quelle question aide à comprendre le cadre ?',['Comment les missions et l’accompagnement sont-ils organisés ?','Pouvez-vous garantir mon succès sans condition ?','Puis-je ignorer toutes les consignes ?'],0,'Comprendre les tâches et l’accompagnement aide à préparer la suite.'),
l('Relire son entraînement','Après une simulation, choisis une chose claire et une chose à améliorer. Vérifie que tu as répondu à la question, donné un exemple et reconnu une limite. Entraîne-toi à reformuler une phrase longue. Le retour automatique de Nunya est une grille de relecture, pas l’avis d’un recruteur. Aucun entretien n’est envoyé ni noté comme une sélection réelle.','À garder : exemple précis.\nÀ améliorer : réponse trop longue.\nProchain essai : expliquer le projet en quatre phrases.','Une amélioration concrète rend le prochain essai utile.','Quel retour est le plus exploitable ?',['Tu es forcément recruté.','Raccourcis la réponse et conserve ton exemple précis.','Tu dois tout changer sans savoir pourquoi.'],1,'Une action concrète permet de préparer un nouvel essai.')]),
('tableurs-pratique','Tableurs : organiser, calculer et vérifier','Spreadsheets: organize and check','business',[
l('Construire une petite table','Une feuille de calcul organise des valeurs en lignes et en colonnes. Donne un nom clair à chaque colonne et garde une même unité dans une colonne. Une table de suivi de cahiers peut contenir quantité, prix unitaire et total. Une cellule vide n’est pas nécessairement zéro : elle peut signaler une information manquante. Ces règles restent utiles dans différents logiciels, même si les boutons changent.','Article | Quantité | Prix unitaire FCFA\nCahier | 3 | 250','Une ligne décrit un article et chaque colonne possède un rôle.','Une cellule vide doit être interprétée…',['automatiquement comme zéro','selon le sens de la donnée manquante','comme le plus grand nombre'],1,'Il faut savoir si la valeur est inconnue, non applicable ou réellement nulle.'),
l('Calculer un total et le contrôler','Une formule commence généralement par le signe égal. Si B2 contient 3 et C2 contient 250, la formule =B2*C2 donne 750. Vérifie le résultat avec un calcul simple avant de recopier la formule. Les séparateurs et les noms de fonctions peuvent varier selon la langue du logiciel ; le raisonnement reste le même.','B2 = 3 ; C2 = 250\nD2 : =B2*C2','D2 affiche 750 dans cet exemple.','Avec B2 = 4 et C2 = 300, =B2*C2 donne…',['304','1 200','750'],1,'4 × 300 = 1 200. Les valeurs de la table et les unités doivent aussi être contrôlées.'),
l('Comprendre une référence qui se déplace','Quand une formule est recopiée, une référence relative peut suivre le déplacement. Copier =B2*C2 de D2 vers D3 donne habituellement =B3*C3. Vérifie les cellules visées, surtout si une formule utilise une valeur fixe. Des références absolues avec des signes dollar peuvent servir à fixer une cellule ; leur usage dépend du calcul voulu.','D2 : =B2*C2\nCopie une ligne plus bas\nD3 : =B3*C3','La formule suit la ligne de l’article suivant.','En copiant une ligne plus bas, B2 devient en référence relative…',['B3','C2','$B$2'],0,'Le numéro de ligne augmente d’une unité ; la colonne B reste la même.'),
l('Choisir un graphique honnête','Un graphique doit répondre à une question. Pour comparer des quantités par catégorie, des barres peuvent être utiles. Donne un titre précis, une unité et une échelle lisible. Vérifie que les données sélectionnées sont les bonnes et qu’un changement d’échelle ne donne pas une impression trompeuse. Un graphique ne prouve pas une cause et ne corrige pas une table mal préparée.','Question : combien de livres ont été prêtés chaque jour ?\nDonnées fictives : lundi 4, mardi 6.\nTitre : Prêts fictifs sur deux jours.','Le titre et l’unité décrivent le périmètre.','Avant de partager un graphique, il faut…',['retirer les unités','vérifier les données, le titre et l’échelle','choisir la couleur avant toute vérification'],1,'La lisibilité et l’exactitude du graphique dépendent d’abord des données et de leur présentation.')]),
('documents-pratique','Documents : structurer et présenter ses idées','Create readable documents','tech',[
l('Organiser le contenu avant la mise en forme','Commence par l’objectif et le public du document. Prépare un titre, deux ou trois sections et les informations essentielles. Un compte rendu de club peut préciser le but, les décisions et les prochaines actions. N’ajoute pas de données personnelles qui ne sont pas nécessaires. La structure doit rester compréhensible même si les couleurs et les images disparaissent.','Titre : Réunion du club\n1. Objectif\n2. Décisions\n3. Prochaines actions','La structure aide le lecteur à trouver une information.','Quel plan aide à retrouver les décisions ?',['Un paragraphe unique sans titre.','Des sections nommées selon leur rôle.','Un titre différent à chaque ligne.'],1,'Des titres clairs permettent de parcourir le document et de comprendre son organisation.'),
l('Utiliser des titres et des listes cohérents','Les styles de titre aident à garder une hiérarchie cohérente. Un titre de section et un sous-titre n’ont pas le même rôle. Une liste peut regrouper des éléments parallèles ; une liste numérotée peut préciser un ordre. Ne remplace pas la structure par des espaces répétés, qui risquent de se déplacer sur un autre écran ou à l’impression.','Titre principal\nSection : Prochaines actions\n1. Relire le texte\n2. Vérifier les informations','La numérotation indique ici un ordre de travail.','Une liste numérotée est particulièrement utile pour…',['indiquer des étapes ordonnées','cacher les actions','remplacer tous les titres'],0,'Les numéros peuvent montrer l’ordre attendu des étapes.'),
l('Nommer les fichiers et garder une version','Un nom de fichier aide à reconnaître un document sans l’ouvrir. Utilise un nom court, un sujet et éventuellement une date ou un numéro de version. Avant un changement important, conserve une copie distincte. Vérifie où la copie est stockée et si elle peut être rouverte. Une sauvegarde ne consiste pas seulement à croire qu’un fichier existe quelque part.','club-compte-rendu-v1\nclub-compte-rendu-v2-relue','Le nom permet de distinguer les versions.','Une sauvegarde utile doit notamment…',['porter un nom secret sans rapport','pouvoir être retrouvée et rouverte','rester uniquement dans une fenêtre non enregistrée'],1,'Une copie n’aide que si elle est accessible et utilisable au moment nécessaire.'),
l('Relire et exporter un document','Relis le fond avant de vérifier la présentation : noms, dates, unités, actions et informations à confirmer. Contrôle ensuite les titres, les coupures de page et la lisibilité à l’impression. Un PDF peut conserver une présentation, mais il faut ouvrir le fichier exporté pour le vérifier. Les formats et les options disponibles varient selon l’outil.','Contrôle : informations → structure → présentation → fichier exporté.','La vérification continue après l’export.','Après avoir exporté un PDF, tu dois…',['supposer qu’il est toujours correct','ouvrir le fichier et vérifier le résultat','effacer immédiatement la version de travail'],1,'L’export peut modifier la mise en page ; ouvrir le fichier permet de voir le résultat réel.')])]
output=[]
for id,title,en,domain,lessons in rows:
 c={'id':id,'title':title,'en':en,'domain':domain,'glyph':'Aa','desc':'Un cours original en français, avec exemples, exercices corrigés et une application à ton projet.','enDesc':'Original French lessons and practice.','category':'COMPÉTENCES PRATIQUES · NUNYA','type':'subject','level':'Débutant','duration':len(lessons)*10,'track':'future','author':'Nunya','status':'brouillon','reviewer':None,'license':'CC BY-SA 4.0','lessons':lessons}
 output.append(c);(root/'content/fr'/(id+'.json')).write_text(json.dumps(c,ensure_ascii=False,indent=2)+'\n')
(root/'dist/data/skill_courses.json').write_text(json.dumps(output,ensure_ascii=False,separators=(',',':')));print('Original practical courses:',len(output))
